from html import escape


REPORT_AR = {'FLARE AI / Research workbench / Run snapshot': 'FLARE AI / مساحة البحث / لقطة التشغيل', 'Synthetic demo only. Not a safety assessment. Verified results apply only within simulated conditions. Atmospheric health and re-ignition risk are not evaluated.': 'عرض اصطناعي فقط. ليس تقييمًا للسلامة. تنطبق نتائج التحقق ضمن ظروف المحاكاة وحدها. لا تُقيّم سلامة الهواء أو خطر إعادة الاشتعال.', 'Run and decision': 'التشغيل والقرار', 'Run identifier': 'معرّف التشغيل', 'Exported': 'وقت التصدير', 'Profile / engine': 'ملف التحقق / المحرك', 'Seed': 'البذرة', 'Virtual time': 'الزمن الافتراضي', 'Combustion': 'الاحتراق', 'Atmosphere': 'الغلاف الجوي', 'Required data': 'البيانات المطلوبة', 'Reason codes': 'رموز الأسباب', 'Parent branch': 'الفرع الأصل', 'Research question': 'السؤال البحثي', 'Evidence and limitations': 'الأدلة والحدود', 'Event ledger': 'سجل الأحداث', 'Sequence': 'التسلسل', 'Time (s)': 'الزمن (ث)', 'Event': 'الحدث', 'Detail': 'التفصيل', 'Observed measurements': 'القياسات المرصودة', 'All persisted observations, sim_unit. Missing channels remain gaps.': 'جميع الأرصاد المحفوظة بوحدة sim_unit. تبقى القنوات المفقودة فجوات.', 'Flame': 'اللهب', 'Thermal': 'الحرارة', 'Ventilation': 'التهوية', 'Open source record': 'فتح سجل المصدر', 'Source summaries provide research context. This synthetic run does not use imported NASA measurements.': 'توفر ملخصات المصادر السياق البحثي. لا يستخدم هذا التشغيل الاصطناعي قياسات NASA المستوردة.', 'Danger': 'خطر', 'Uncertain': 'غير مؤكد', 'Verified': 'تم التحقق', 'Verified within simulated conditions': 'تم التحقق ضمن ظروف المحاكاة', 'elevated': 'مرتفع', 'declining': 'متناقص', 'valid': 'صالح', 'invalid': 'غير صالح', 'Unknown': 'غير معروف', 'Original run': 'تشغيل أصلي', 'Missing': 'مفقود'}
REPORT_AR.update({"Plan approved:": "اعتماد الخطة:", "Continuous hold: 30s after a valid 10s danger clearance.": "فترة تحقق متواصلة مدتها 30 ثانية بعد استيفاء شروط زوال الخطر لمدة 10 ثوانٍ."})


def render_report(payload, language="en"):
    tr = lambda value: REPORT_AR.get(value, value) if language == "ar" else value
    run=payload['run']
    decision=run.get('decision',{})
    esc=lambda value: escape(str(value))
    source_rows=''.join(f'<li><strong>{esc(e["reference"])}</strong>: {esc(e["title"])}<br>{esc(e["note"])}'+(f'<br><a href="{esc(e["url"])}">{tr('Open source record')}</a>' if e.get('url') else '')+'</li>' for e in payload['evidence'])
    event_rows=''.join(f'<tr><td>{e["seq"]}</td><td>{e["t"]}</td><td>{esc(e["type"])}</td><td>{esc(e.get("action") or e.get("decision",{}).get("label", ""))}</td></tr>' for e in payload['events'])
    channels=['flame_presence','thermal_excess','co_proxy','ventilation_proxy','co2_proxy']
    measurement_rows=''
    for frame in payload['frames']:
        sample=frame['sample']
        values=''.join('<td>'+(tr('Missing') if sample.get(c) is None else f'{sample[c]:.4f}')+'</td>' for c in channels)
        measurement_rows+=f'<tr><th scope="row">{sample["t"]}</th>{values}<td>{esc(frame["decision"]["combustion_status"])}</td></tr>'
    return f'''<!doctype html><html lang="{language}" dir="{"rtl" if language == "ar" else "ltr"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLARE AI · {esc(run['name'])}</title><style>
    body{{font:14px/1.6 Arial,sans-serif;color:#252b28;max-width:1000px;margin:40px auto;padding:24px}}h1{{font-size:32px;line-height:1.2}}h2{{margin-top:40px}}.note{{background:#f7eee7;padding:16px;border:1px solid #d5b89f}}dl{{display:grid;grid-template-columns:160px 1fr;gap:8px}}dt{{color:#626960}}dd{{margin:0;overflow-wrap:anywhere}}table{{width:100%;border-collapse:collapse;font-size:11px}}th,td{{padding:8px;text-align:start;border-bottom:1px solid #dfe3da}}thead{{background:#f1f2ed}}a{{color:#a64d28}}li{{margin-bottom:16px}}caption{{text-align:start;margin-bottom:12px}}@media print{{body{{margin:0;padding:8px}}thead{{display:table-header-group}}tr{{break-inside:avoid}}h2{{break-after:avoid}}}}
    </style></head><body><p>{tr('FLARE AI / Research workbench / Run snapshot')}</p><h1>{esc(run['name'])}</h1><div class="note">{tr('Synthetic demo only. Not a safety assessment. Verified results apply only within simulated conditions. Atmospheric health and re-ignition risk are not evaluated.')}</div>
    <h2>{tr('Run and decision')}</h2><dl><dt>{tr('Run identifier')}</dt><dd>{esc(run['id'])}</dd><dt>{tr('Exported')}</dt><dd>{esc(payload['exported_at'])}</dd><dt>{tr('Profile / engine')}</dt><dd>synthetic-v1 / {esc(run.get('engine_version','0.1.0'))}</dd><dt>{tr('Seed')}</dt><dd>{run['seed']}</dd><dt>{tr('Virtual time')}</dt><dd>{run['t']} seconds</dd><dt>{tr('Combustion')}</dt><dd>{esc(tr(decision.get('label','Unknown')))}</dd><dt>{tr('Atmosphere')}</dt><dd>{esc(tr(decision.get('atmosphere_status','unknown')))}</dd><dt>{tr('Required data')}</dt><dd>{esc(tr(decision.get('required_quality','unknown')))}</dd><dt>{tr('Reason codes')}</dt><dd>{esc(', '.join(decision.get('reason_codes',[])))}</dd><dt>{tr('Parent branch')}</dt><dd>{esc(run.get('parent_id') or 'Original run')}</dd></dl>
    <h2>{tr('Research question')}</h2><p>{esc(payload['scenario']['question'])}</p><p>{tr("Plan approved:")} {esc(payload['plan'].get('approved_at','Unknown'))}. {tr("Continuous hold: 30s after a valid 10s danger clearance.")}</p>
    <h2>{tr('Evidence and limitations')}</h2><p>{tr('Source summaries provide research context. This synthetic run does not use imported NASA measurements.')}</p><ul>{source_rows}</ul>
    <h2>{tr('Event ledger')}</h2><table><thead><tr><th scope="col">{tr('Sequence')}</th><th scope="col">{tr('Time (s)')}</th><th scope="col">{tr('Event')}</th><th scope="col">{tr('Detail')}</th></tr></thead><tbody>{event_rows}</tbody></table>
    <h2>{tr('Observed measurements')}</h2><table><caption>{tr('All persisted observations, sim_unit. Missing channels remain gaps.')}</caption><thead><tr><th scope="col">{tr('Time (s)')}</th><th scope="col">{tr('Flame')}</th><th scope="col">{tr('Thermal')}</th><th scope="col">CO</th><th scope="col">{tr('Ventilation')}</th><th scope="col">CO2</th><th scope="col">{tr('Combustion')}</th></tr></thead><tbody>{measurement_rows}</tbody></table></body></html>'''
